    "officialId": "comp-582",
    "officialUrl": "https://coss.com/origin/r/comp-582.json",
    "rawCode": "import {\n  FileTextIcon,\n  GlobeIcon,\n  HomeIcon,\n  LayersIcon,\n  UsersIcon,\n} from \"lucide-react\";\nimport { useId } from \"react\";\n\nimport Logo from \"@/registry/default/components/navbar-components/logo\";\nimport ThemeToggle from \"@/registry/default/components/navbar-components/theme-toggle\";\nimport UserMenu from \"@/registry/default/components/navbar-components/user-menu\";\nimport { Button } from \"@/registry/default/ui/button\";\nimport {\n  NavigationMenu,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n} from \"@/registry/default/ui/navigation-menu\";\nimport {\n  Popover,\n  PopoverContent,\n  PopoverTrigger,\n} from \"@/registry/default/ui/popover\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from \"@/registry/default/ui/select\";\nimport {\n  Tooltip,\n  TooltipContent,\n  TooltipProvider,\n  TooltipTrigger,\n} from \"@/registry/default/ui/tooltip\";\n\n// Navigation links with icons for desktop icon-only navigation\nconst navigationLinks = [\n  { active: true, href: \"#\", icon: HomeIcon, label: \"Dashboard\" },\n  { href: \"#\", icon: LayersIcon, label: \"Projects\" },\n  { href: \"#\", icon: FileTextIcon, label: \"Documentation\" },\n  { href: \"#\", icon: UsersIcon, label: \"Team\" },\n];\n\n// Language options\nconst languages = [\n  { label: \"En\", value: \"en\" },\n  { label: \"Es\", value: \"es\" },\n  { label: \"Fr\", value: \"fr\" },\n  { label: \"De\", value: \"de\" },\n  { label: \"Ja\", value: \"ja\" },\n];\n\nexport default function Component() {\n  const id = useId();\n\n  return (\n    <header className=\"border-b px-4 md:px-6\">\n      <div className=\"flex h-16 items-center justify-between gap-4\">\n        {/* Left side */}\n        <div className=\"flex flex-1 items-center gap-2\">\n          {/* Mobile menu trigger */}\n          <Popover>\n            <PopoverTrigger asChild>\n              <Button\n                className=\"group size-8 md:hidden\"\n                size=\"icon\"\n                variant=\"ghost\"\n              >\n                <svg\n                  className=\"pointer-events-none\"\n                  fill=\"none\"\n                  height={16}\n                  stroke=\"currentColor\"\n                  strokeLinecap=\"round\"\n                  strokeLinejoin=\"round\"\n                  strokeWidth=\"2\"\n                  viewBox=\"0 0 24 24\"\n                  width={16}\n                  xmlns=\"http://www.w3.org/2000/svg\"\n                >\n                  <path\n                    className=\"-translate-y-[7px] origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-x-0 group-aria-expanded:translate-y-0 group-aria-expanded:rotate-315\"\n                    d=\"M4 12L20 12\"\n                  />\n                  <path\n                    className=\"origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.8)] group-aria-expanded:rotate-45\"\n                    d=\"M4 12H20\"\n                  />\n                  <path\n                    className=\"origin-center translate-y-[7px] transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-y-0 group-aria-expanded:rotate-135\"\n                    d=\"M4 12H20\"\n                  />\n                </svg>\n              </Button>\n            </PopoverTrigger>\n            <PopoverContent align=\"start\" className=\"w-36 p-1 md:hidden\">\n              <NavigationMenu className=\"max-w-none *:w-full\">\n                <NavigationMenuList className=\"flex-col items-start gap-0 md:gap-2\">\n                  {navigationLinks.map((link, _index) => {\n                    const Icon = link.icon;\n                    return (\n                      <NavigationMenuItem className=\"w-full\" key={link.label}>\n                        <NavigationMenuLink\n                          active={link.active}\n                          className=\"flex-row items-center gap-2 py-1.5\"\n                          href={link.href}\n                        >\n                          <Icon\n                            aria-hidden=\"true\"\n                            className=\"text-muted-foreground\"\n                            size={16}\n                          />\n                          <span>{link.label}</span>\n                        </NavigationMenuLink>\n                      </NavigationMenuItem>\n                    );\n                  })}\n                </NavigationMenuList>\n              </NavigationMenu>\n            </PopoverContent>\n          </Popover>\n          <div className=\"flex items-center gap-6\">\n            {/* Logo */}\n            <a className=\"text-primary hover:text-primary/90\" href=\"#\">\n              <Logo />\n            </a>\n            {/* Desktop navigation - icon only */}\n            <NavigationMenu className=\"hidden md:flex\">\n              <NavigationMenuList className=\"gap-2\">\n                <TooltipProvider>\n                  {navigationLinks.map((link) => (\n                    <NavigationMenuItem key={link.label}>\n                      <Tooltip>\n                        <TooltipTrigger asChild>\n                          <NavigationMenuLink\n                            className=\"flex size-8 items-center justify-center p-1.5\"\n                            href={link.href}\n                          >\n                            <link.icon aria-hidden=\"true\" size={20} />\n                            <span className=\"sr-only\">{link.label}</span>\n                          </NavigationMenuLink>\n                        </TooltipTrigger>\n                        <TooltipContent\n                          className=\"px-2 py-1 text-xs\"\n                          side=\"bottom\"\n                        >\n                          <p>{link.label}</p>\n                        </TooltipContent>\n                      </Tooltip>\n                    </NavigationMenuItem>\n                  ))}\n                </TooltipProvider>\n              </NavigationMenuList>\n            </NavigationMenu>\n          </div>\n        </div>\n        {/* Right side */}\n        <div className=\"flex items-center gap-2\">\n          {/* Theme toggle */}\n          <ThemeToggle />\n          {/* Language selector */}\n          <Select defaultValue=\"en\">\n            <SelectTrigger\n              aria-label=\"Select language\"\n              className=\"h-8 border-none px-2 shadow-none hover:bg-accent hover:text-accent-foreground [&>svg]:shrink-0 [&>svg]:text-muted-foreground/80\"\n              id={`language-${id}`}\n            >\n              <GlobeIcon aria-hidden=\"true\" size={16} />\n              <SelectValue className=\"hidden sm:inline-flex\" />\n            </SelectTrigger>\n            <SelectContent className=\"[&_*[role=option]>span]:start-auto [&_*[role=option]>span]:end-2 [&_*[role=option]>span]:flex [&_*[role=option]>span]:items-center [&_*[role=option]>span]:gap-2 [&_*[role=option]]:ps-2 [&_*[role=option]]:pe-8\">\n              {languages.map((lang) => (\n                <SelectItem key={lang.value} value={lang.value}>\n                  <span className=\"flex items-center gap-2\">\n                    <span className=\"truncate\">{lang.label}</span>\n                  </span>\n                </SelectItem>\n              ))}\n            </SelectContent>\n          </Select>\n          {/* User menu */}\n          <UserMenu />\n        </div>\n      </div>\n    </header>\n  );\n}\n",
