    "rawCode": "import Logo from \"@/registry/default/components/navbar-components/logo\";\nimport { Button } from \"@/registry/default/ui/button\";\nimport {\n  NavigationMenu,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n} from \"@/registry/default/ui/navigation-menu\";\nimport {\n  Popover,\n  PopoverContent,\n  PopoverTrigger,\n} from \"@/registry/default/ui/popover\";\n\n// Navigation links array to be used in both desktop and mobile menus\nconst navigationLinks = [\n  { active: true, href: \"#\", label: \"Home\" },\n  { href: \"#\", label: \"Features\" },\n  { href: \"#\", label: \"Pricing\" },\n  { href: \"#\", label: \"About\" },\n];\n\nexport default function Component() {\n  return (\n    <header className=\"border-b px-4 md:px-6\">\n      <div className=\"flex h-16 justify-between gap-4\">\n        {/* Left side */}\n        <div className=\"flex gap-2\">\n          <div className=\"flex items-center md:hidden\">\n            {/* Mobile menu trigger */}\n            <Popover>\n              <PopoverTrigger asChild>\n                <Button className=\"group size-8\" size=\"icon\" variant=\"ghost\">\n                  <svg\n                    className=\"pointer-events-none\"\n                    fill=\"none\"\n                    height={16}\n                    stroke=\"currentColor\"\n                    strokeLinecap=\"round\"\n                    strokeLinejoin=\"round\"\n                    strokeWidth=\"2\"\n                    viewBox=\"0 0 24 24\"\n                    width={16}\n                    xmlns=\"http://www.w3.org/2000/svg\"\n                  >\n                    <path\n                      className=\"-translate-y-[7px] origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-x-0 group-aria-expanded:translate-y-0 group-aria-expanded:rotate-315\"\n                      d=\"M4 12L20 12\"\n                    />\n                    <path\n                      className=\"origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.8)] group-aria-expanded:rotate-45\"\n                      d=\"M4 12H20\"\n                    />\n                    <path\n                      className=\"origin-center translate-y-[7px] transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-y-0 group-aria-expanded:rotate-135\"\n                      d=\"M4 12H20\"\n                    />\n                  </svg>\n                </Button>\n              </PopoverTrigger>\n              <PopoverContent align=\"start\" className=\"w-36 p-1 md:hidden\">\n                <NavigationMenu className=\"max-w-none *:w-full\">\n                  <NavigationMenuList className=\"flex-col items-start gap-0 md:gap-2\">\n                    {navigationLinks.map((link, index) => (\n                      <NavigationMenuItem\n                        className=\"w-full\"\n                        key={String(index)}\n                      >\n                        <NavigationMenuLink\n                          data-active={link.active ? \"\" : undefined}\n                          className=\"py-1.5\"\n                          href={link.href}\n                        >\n                          {link.label}\n                        </NavigationMenuLink>\n                      </NavigationMenuItem>\n                    ))}\n                  </NavigationMenuList>\n                </NavigationMenu>\n              </PopoverContent>\n            </Popover>\n          </div>\n          {/* Main nav */}\n          <div className=\"flex items-center gap-6\">\n            <a className=\"text-primary hover:text-primary/90\" href=\"#\">\n              <Logo />\n            </a>\n            {/* Navigation menu */}\n            <NavigationMenu className=\"h-full *:h-full max-md:hidden\">\n              <NavigationMenuList className=\"h-full gap-2\">\n                {navigationLinks.map((link, index) => (\n                  <NavigationMenuItem className=\"h-full\" key={String(index)}>\n                    <NavigationMenuLink\n                      data-active={link.active ? \"\" : undefined}\n                      className=\"h-full justify-center rounded-none border-transparent border-y-2 py-1.5 font-medium text-muted-foreground hover:border-b-primary hover:bg-transparent hover:text-primary data-[active]:border-b-primary data-[active]:bg-transparent!\"\n                      href={link.href}\n                    >\n                      {link.label}\n                    </NavigationMenuLink>\n                  </NavigationMenuItem>\n                ))}\n              </NavigationMenuList>\n            </NavigationMenu>\n          </div>\n        </div>\n        {/* Right side */}\n        <div className=\"flex items-center gap-2\">\n          <Button asChild className=\"text-sm\" size=\"sm\" variant=\"ghost\">\n            <a href=\"#\">Sign In</a>\n          </Button>\n          <Button asChild className=\"text-sm\" size=\"sm\">\n            <a href=\"#\">Get Started</a>\n          </Button>\n        </div>\n      </div>\n    </header>\n  );\n}\n",
