    "rawCode": "import { GlobeIcon } from \"lucide-react\";\n\nimport { Button } from \"@/registry/default/ui/button\";\nimport {\n  Tooltip,\n  TooltipContent,\n  TooltipProvider,\n  TooltipTrigger,\n} from \"@/registry/default/ui/tooltip\";\n\nexport default function Component() {\n  return (\n    <TooltipProvider delayDuration={0}>\n      <Tooltip>\n        <TooltipTrigger asChild>\n          <Button size=\"sm\" variant=\"outline\">\n            W/ icon\n          </Button>\n        </TooltipTrigger>\n        <TooltipContent className=\"dark py-3\">\n          <div className=\"flex gap-3\">\n            <GlobeIcon\n              aria-hidden=\"true\"\n              className=\"mt-0.5 shrink-0 opacity-60\"\n              size={16}\n            />\n            <div className=\"space-y-1\">\n              <p className=\"font-medium text-[13px]\">\n                Tooltip with title and icon\n              </p>\n              <p className=\"text-muted-foreground text-xs\">\n                Tooltips are made to be highly customizable, with features like\n                dynamic placement, rich content, and a robust API.\n              </p>\n            </div>\n          </div>\n        </TooltipContent>\n      </Tooltip>\n    </TooltipProvider>\n  );\n}\n",
