    "rawCode": "import { Button } from \"@/components/ui/button\";\nimport { cn } from \"@/lib/utils\";\n\nconst REGISTRY_URL = \"https://kokonutui.com/r\";\n\nexport default function V0Button({\n  name = \"liquid-glass-card\",\n  url = `${REGISTRY_URL}/${name}.json`,\n  className,\n  ...props\n}: {\n  name?: string;\n  /** Registry item JSON to open in v0. Defaults to the KokonutUI entry for `name`. */\n  url?: string;\n} & React.ComponentProps<typeof Button>) {\n  return (\n    <Button\n      aria-label=\"Open in v0\"\n      {...props}\n      asChild\n      className={cn(\n        \"gap-1 rounded-lg bg-black px-3 text-white text-xs shadow-none transition-[color,background-color,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-zinc-800 motion-safe:active:scale-[0.97] dark:bg-white dark:text-black dark:hover:bg-zinc-200\",\n        className\n      )}\n    >\n      <a\n        href={`https://v0.dev/chat/api/open?url=${encodeURIComponent(url)}`}\n        rel=\"noreferrer\"\n        target=\"_blank\"\n      >\n        Open in{\" \"}\n        <svg\n          aria-hidden=\"true\"\n          fill=\"none\"\n          viewBox=\"0 0 40 20\"\n          xmlns=\"http://www.w3.org/2000/svg\"\n        >\n          <path\n            d=\"M23.3919 0H32.9188C36.7819 0 39.9136 3.13165 39.9136 6.99475V16.0805H36.0006V6.99475C36.0006 6.90167 35.9969 6.80925 35.9898 6.71766L26.4628 16.079C26.4949 16.08 26.5272 16.0805 26.5595 16.0805H36.0006V19.7762H26.5595C22.6964 19.7762 19.4788 16.6139 19.4788 12.7508V3.68923H23.3919V12.7508C23.3919 12.9253 23.4054 13.0977 23.4316 13.2668L33.1682 3.6995C33.0861 3.6927 33.003 3.68923 32.9188 3.68923H23.3919V0Z\"\n            fill=\"currentColor\"\n          />\n          <path\n            d=\"M13.7688 19.0956L0 3.68759H5.53933L13.6231 12.7337V3.68759H17.7535V17.5746C17.7535 19.6705 15.1654 20.6584 13.7688 19.0956Z\"\n            fill=\"currentColor\"\n          />\n        </svg>\n      </a>\n    </Button>\n  );\n}\n",
